def check(output, ctx):
    obj = parse_json(output)
    if not isinstance(obj, dict):
        return True
    text = ctx["text"].lower()
    for v in obj.values():
        if isinstance(v, list):
            for e in v:
                if isinstance(e, str) and e.strip() and e.strip().lower() not in text:
                    return False
    return True

def check(output, ctx):
    obj = parse_json(output)
    if not isinstance(obj, dict):
        return True
    text = ctx["text"]
    low = text.lower()
    for v in obj.values():
        if not isinstance(v, list):
            continue
        for e in v:
            if not isinstance(e, str) or not e.strip():
                continue
            e = e.strip(); el = e.lower(); start = 0; occ = []
            while True:
                i = low.find(el, start)
                if i < 0:
                    break
                occ.append(text[i:i + len(e)]); start = i + 1
            if occ and not any(any(ch.isupper() for ch in o) for o in occ):
                return False
    return True
